const trig = $('Sub-workflow Input').first()?.json || {};
const ctx = $('Resolve Tenant Context').first()?.json || {};
const scope = String(trig.scope || 'search').toLowerCase();
const limit = Math.min(parseInt(trig.limit, 10) || 10, 50);
const recordId = String(trig.recordId || '').trim();
const query = String(trig.query || '').trim();
const orgCfg = (ctx.orgConfig && typeof ctx.orgConfig === 'object') ? ctx.orgConfig : {};
const fbCfg = (trig.fallbackOrgConfig && typeof trig.fallbackOrgConfig === 'object') ? trig.fallbackOrgConfig : {};
const cfg = Object.assign({}, fbCfg, orgCfg);
const envelope = {
  ok: false, status: 'refused', reasonCode: 'none', guidance: 'none', userMessage: null,
  connectorId: 'internal.kb', organizationId: ctx.organizationId || null, userId: ctx.userId || null,
  contextSource: ctx.contextSource || 'fallback', degraded: ctx.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: 'kb-' + ($execution.id || 'na') + '-' + Date.now(), workflow: 'prism-16-knowledge-base-service', scope: scope }
};
function refuse(code, msg, guidance) { envelope.status = 'refused'; envelope.reasonCode = code; envelope.userMessage = msg; envelope.guidance = guidance; return [{ json: envelope }]; }
if (ctx.enabled === false) return refuse('connector_disabled', 'Knowledge Base is turned off for you - enable it in Connections.', 'enable');
if (ctx.entitlement === false) return refuse('not_entitled', 'Your account does not have access to Knowledge Base - ask your admin to unlock it.', 'request_access');
if (!query) return refuse('empty', 'Ask a question or provide a topic to search the knowledge base.', 'none');
const matchCount = Math.min(parseInt(trig.matchCount, 10) || 5, 20);
const supabaseUrl = String(trig.supabaseUrl || cfg.supabaseUrl || '').trim().replace(/\/+$/, '');
if (!supabaseUrl) return refuse('org_misconfigured', 'The knowledge base is not configured for your organization yet - ask your admin to set it up.', 'none');
return [{ json: Object.assign({}, envelope, { ok: true, status: 'pending', supabaseUrl: supabaseUrl, kbOrganizationId: ctx.organizationId || null, kbQuery: query, matchCount: matchCount }) }];

const res = $input.first()?.json || {};
const meta = $('Gate & Build Request').first()?.json || {};
const scope = (meta.diagnostics && meta.diagnostics.scope) || 'unknown';
const envelope = {
  ok: false, status: 'error', reasonCode: 'provider_error', guidance: 'retry',
  userMessage: 'Knowledge Base returned an error - try again shortly. If it persists, check the connection in Connections.',
  connectorId: 'internal.kb', organizationId: meta.organizationId || null, userId: meta.userId || null,
  contextSource: meta.contextSource || 'fallback', degraded: meta.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: (meta.diagnostics && meta.diagnostics.requestId) || ('kb-' + Date.now()), workflow: 'prism-16-knowledge-base-service' }
};
const httpStatus = (res.error && (res.error.status || res.error.statusCode)) || res.statusCode || null;
const errCode = res.error && res.error.code ? String(res.error.code) : '';
function finishSuccess() { envelope.ok = true; envelope.status = 'success'; envelope.reasonCode = 'none'; envelope.guidance = 'none'; envelope.userMessage = null; envelope.error = null; }
if (res && res.message && !Array.isArray(res)) { envelope.reasonCode = 'provider_error'; envelope.userMessage = 'Knowledge base search failed - ' + String(res.message) + '. If this persists, verify the org-scoped match_documents RPC is deployed (see docs/SUPABASE_PRISM_V2_PROMPTS.md).'; envelope.error = { provider: 'supabase', httpStatus: httpStatus || null, message: String(res.message), retryable: false }; return [{ json: envelope }]; }
const raw = Array.isArray(res) ? res : (Array.isArray(res.documents) ? res.documents : []);
const records = raw.map(function (d, i) { return {
  id: String(d.id || i), content: d.content || '',
  similarity: d.similarity != null ? Number(d.similarity) : null,
  source: (d.metadata && (d.metadata.title || d.metadata.source)) || 'document'
}; });
finishSuccess(); envelope.records = records; envelope.total = records.length;
return [{ json: envelope }];
